import React, { useEffect, useState } from "react";
import axios from "axios";

function QuizTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [courseId, setCourseId] = useState("");
  const [title, setTitle] = useState("");
  const [difficulty, setDifficulty] = useState("easy");
  const [numQuestions, setNumQuestions] = useState(3);

  const [quizId, setQuizId] = useState(null);

  const [question, setQuestion] = useState("");
  const [options, setOptions] = useState(["", "", "", ""]);
  const [correctIndex, setCorrectIndex] = useState(null);

  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/courses")
      .then((res) => setCourses(res.data.courses || []))
      .catch((err) => console.error(err));
  }, []);

  const generateQuiz = async () => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/generate-quiz", {
        course_id: parseInt(courseId),
        teacher_id: parseInt(teacherId),
        title: title,
        difficulty: difficulty,
        num_questions: parseInt(numQuestions)
      });

      setQuizId(res.data.quiz_id);
      alert(res.data.message);
    } catch (err) {
      console.error(err);
      alert("Quiz generation failed");
    }
  };

  const createManualQuiz = async () => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/create-quiz", {
        course_id: parseInt(courseId),
        teacher_id: parseInt(teacherId),
        title: title
      });

      setQuizId(res.data.quiz_id);
      alert("Manual quiz created");
    } catch (err) {
      console.error(err);
      alert("Manual quiz creation failed");
    }
  };

  const addQuestion = async () => {
    if (correctIndex === null) {
      alert("Select correct answer");
      return;
    }

    try {
      await axios.post("http://127.0.0.1:8000/add-question", {
        quiz_id: quizId,
        question: question,
        option1: options[0],
        option2: options[1],
        option3: options[2],
        option4: options[3],
        correct_answer: options[correctIndex]
      });

      alert("Question added");

      setQuestion("");
      setOptions(["", "", "", ""]);
      setCorrectIndex(null);
    } catch (err) {
      console.error(err);
      alert("Failed to add question");
    }
  };

  return (
    <div>
      <h2 style={{ color: "#6a1b9a", marginBottom: "20px" }}>
        Quiz Teacher Panel
      </h2>

      <div style={card}>
        <h3>Create / Generate Quiz</h3>

        <select
          value={courseId}
          onChange={(e) => setCourseId(e.target.value)}
          style={input}
        >
          <option value="">Select Course / Subject</option>
          {courses.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title} {c.subject_code ? `(${c.subject_code})` : ""}
            </option>
          ))}
        </select>

        <input
          placeholder="Quiz Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={input}
        />

        <select
          value={difficulty}
          onChange={(e) => setDifficulty(e.target.value)}
          style={input}
        >
          <option value="easy">Easy</option>
          <option value="medium">Medium</option>
          <option value="hard">Hard</option>
        </select>

        <input
          type="number"
          min="1"
          max="10"
          value={numQuestions}
          onChange={(e) => setNumQuestions(e.target.value)}
          style={input}
        />

        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <button onClick={generateQuiz} style={btn}>
            Auto Generate Quiz
          </button>

          <button onClick={createManualQuiz} style={btnSecondary}>
            Create Manual Quiz
          </button>
        </div>
      </div>

      {quizId && (
        <div style={card}>
          <h3>Add Manual Question</h3>

          <input
            placeholder="Question"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            style={input}
          />

          {options.map((opt, i) => (
            <div key={i} style={optionRow}>
              <input
                placeholder={`Option ${i + 1}`}
                value={opt}
                onChange={(e) => {
                  const arr = [...options];
                  arr[i] = e.target.value;
                  setOptions(arr);
                }}
                style={{ ...input, marginBottom: 0 }}
              />

              <label style={{ minWidth: "120px" }}>
                <input
                  type="radio"
                  name="correct"
                  checked={correctIndex === i}
                  onChange={() => setCorrectIndex(i)}
                />
                {" "}Correct
              </label>
            </div>
          ))}

          <button onClick={addQuestion} style={btn}>
            Add Question
          </button>
        </div>
      )}
    </div>
  );
}

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "14px",
  marginBottom: "20px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
};

const input = {
  display: "block",
  width: "100%",
  marginBottom: "12px",
  padding: "10px",
  borderRadius: "8px",
  border: "1px solid #ccc"
};

const optionRow = {
  display: "flex",
  gap: "10px",
  alignItems: "center",
  marginBottom: "10px"
};

const btn = {
  background: "#7b1fa2",
  color: "#fff",
  padding: "10px 14px",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer"
};

const btnSecondary = {
  background: "#1565c0",
  color: "#fff",
  padding: "10px 14px",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer"
};

export default QuizTeacher;
